/** Warnings a drawing is *supposed* to produce.
 *
 * `smoke.mjs` treats any warning as a problem, which is what makes silence there a signal. A few
 * fixtures exist precisely to make a guard fire, so their warning is the assertion rather than a
 * regression — `dimension-degenerate.dxf` is generated by
 * `fixtures/gen/generate.py` with two coincident measurement points so that
 * `LinearDimension`'s validity check has something to reject.
 *
 * Listing one here keeps the sweep honest in both directions: the expected warning no longer
 * fails the run, and a file that *stops* warning fails it instead — a guard that quietly stopped
 * firing is exactly the regression this fixture exists to catch.
 *
 * Keys are repo-relative paths with forward slashes, so `test-data/` drawings can be listed too.
 * Each entry is matched as a **substring** of the warning message; leave the handle out, since
 * handles move when a fixture is regenerated. Count is deliberately not pinned — a dimension is
 * decomposed twice (once by `_FetchFonts()`), so its warnings come in pairs today and would not
 * if that were fixed.
 */
export const ExpectedWarnings = {
    "test/fixtures/block-recursive.dxf": [
        "Recursive block reference"
    ],
    "test/fixtures/dimension-degenerate.dxf": [
        "Invalid dimension geometry detected"
    ]
}
